def _import(name):
    """从本 skill 的 src 目录导入真实模块; 失败返回 (None, 异常)。"""
    src = str(SRC_DIR)                                                            # 包根即 skill 根: 注入它才能 import 到本 skill 的模块
    if os.path.isdir(src) and src not in sys.path:                                        # 目录不存在就不注入: 注入一个不存在的路径会掩盖真实导入错误
        sys.path.insert(0, src)                                                                     # 挂到最前: 否则可能先解析到别的同名包
    try:
        return importlib.import_module(name), None
    except Exception as _e:  # 依赖缺失等 ->由测试函数决策 skip
        return None, _e



def test_gen_package_importable():
    """importlib.import_module("astro_<name>") 真实包可导入; 依赖缺失时显式 skip。"""
    mod, err = _import(PKG)  # 缺依赖时 skip 而不是 fail: 环境问题不该伪装成用例失败
    if mod is None:                                                                                 # 导入失败才进 skip 分支
        # 依赖缺失是环境事实而非回归: 显式 skip, 不用 pass 伪装绿灯
        pytest.skip(f"dependency missing for {PKG}: {err}")
    assert mod is not None                                                                # 走到这里必须真的导入了: 否则前面的 skip 已经把它拦下


def test_gen_spec_algorithms_importable():
    """spec.algorithms 的每个 (module, name) 均可导入且可调用 (源头为真源码 grep)。"""
    spec = get_spec_data()                                                                         # 取 spec 切片: 算法的权威声明在这里
    algos = spec["skills"][SKILL]["algorithms"]                                         # 按 skill 键取算法清单: 别 skill 的算法不归本仓管
    for a in algos:                                                                                 # 逐个算法条目
        mod, err = _import(a["module"])                                                             # 逐条导入它声明的模块
        if mod is None:                                                                          # 导入失败同样走 skip: 依赖缺失是环境事实
            pytest.skip(f"dependency missing for {a['module']}: {err}")
        assert hasattr(mod, a["name"]), f"{a['module']}.{a['name']} 缺失"  # 符号必须存在且可调用: 只可导入的模块等于没有能力
        assert callable(getattr(mod, a["name"]))
